<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class SubscriptionCatalogSeeder extends Seeder
{
 public function run():void{$now=now();$plans=['basic'=>['Basic','For photographers starting a professional client-delivery workflow.',10,20000,20000,0,0,10],'standard'=>['Standard','For active studios managing regular gallery delivery.',20,100000,200000,5000,5,null],'essential'=>['Essential','For growing studios with larger delivery operations.',30,200000,400000,10000,5,null],'premium'=>['Premium','For high-volume studios requiring the broadest LensPic plan.',40,500000,1000000,25000,5,null]];foreach($plans as$code=>[$name,$description,$order,$photos,$reuse,$video,$seats,$groups])DB::table('subscription_plans')->insertOrIgnore(['uuid'=>(string)Str::uuid(),'code'=>$code,'name'=>$name,'slug'=>$code,'short_description'=>$description,'rank'=>$order,'display_order'=>$order,'is_active'=>true,'is_public'=>true,'is_recommended'=>false,'photo_storage_limit'=>$photos,'photo_reuse_limit'=>$reuse,'video_storage_mb'=>$video,'team_seat_limit'=>$seats,'group_limit'=>$groups,'guest_limit'=>null,'grace_period_days'=>0,'version'=>1,'created_at'=>$now,'updated_at'=>$now]);DB::table('subscription_plans')->insertOrIgnore(['uuid'=>(string)Str::uuid(),'code'=>'free','name'=>'Free','slug'=>'free','short_description'=>'Private starter access.','rank'=>0,'display_order'=>0,'is_active'=>true,'is_public'=>false,'is_recommended'=>false,'photo_storage_limit'=>100,'photo_reuse_limit'=>100,'video_storage_mb'=>0,'team_seat_limit'=>0,'group_limit'=>3,'guest_limit'=>null,'grace_period_days'=>0,'version'=>1,'created_at'=>$now,'updated_at'=>$now]);$prices=['basic'=>[99900,349000],'standard'=>[179900,749000],'essential'=>[359900,1499000],'premium'=>[689900,2999000]];foreach($prices as$code=>[$q,$y]){$id=DB::table('subscription_plans')->where('code',$code)->value('id');foreach(['quarterly'=>$q,'yearly'=>$y]as$i=>$amount)if(!DB::table('subscription_plan_prices')->where('subscription_plan_id',$id)->where('billing_interval',$i)->exists())DB::table('subscription_plan_prices')->insert(['subscription_plan_id'=>$id,'billing_interval'=>$i,'currency'=>'INR','base_amount_paise'=>$amount,'gst_rate_basis_points'=>1800,'is_active'=>true,'effective_from'=>'2026-08-29 00:00:00','created_at'=>$now,'updated_at'=>$now]);}$features=[['photo_storage','Photo Storage','images','integer','photos','limits'],['photo_reuse','Photo Reuse','refresh','integer','photos','limits'],['video_storage','Video Storage','video','integer','MB','limits'],['team_seats','Team Seats','shield-users','integer','seats','limits'],['group_limit','Group Limit','layout-grid','integer','groups','limits'],['guest_limit','Guest Limit','users','integer','guests','limits'],['business_branding','Business Branding','palette','boolean',null,'branding'],['bulk_download','Bulk Download','download','boolean',null,'delivery'],['client_favourites','Client Favourites','heart','boolean',null,'delivery'],['download_controls','Download Controls','sliders','boolean',null,'delivery'],['gallery_themes','Gallery Themes','layout-grid','boolean',null,'branding'],['analytics','Analytics','chart-users','boolean',null,'insights'],['participant_information','Participant Information','users','boolean',null,'insights'],['watermark','Watermark','stamp','boolean',null,'branding'],['portfolio_website','Portfolio Website','globe','boolean',null,'branding'],['team_login','Team Login and Controls','shield-users','boolean',null,'team'],['private_client_galleries','Private Client Galleries','lock','boolean',null,'privacy'],['secure_group_sharing','Secure Group Sharing','share','boolean',null,'privacy'],['find_my_photos','Find My Photos','scan-face','boolean',null,'biometric'],['priority_support','Priority Support','headphones','boolean',null,'support']];foreach($features as$n=>[$code,$name,$icon,$type,$unit,$category])DB::table('subscription_features')->insertOrIgnore(['code'=>$code,'name'=>$name,'icon'=>$icon,'value_type'=>$type,'unit'=>$unit,'category'=>$category,'is_active'=>true,'display_order'=>($n+1)*10,'created_at'=>$now,'updated_at'=>$now]);$matrix=['basic'=>['business_branding','bulk_download','private_client_galleries','secure_group_sharing','find_my_photos'],'standard'=>['business_branding','client_favourites','bulk_download','portfolio_website','team_login','private_client_galleries','find_my_photos'],'essential'=>['business_branding','client_favourites','download_controls','bulk_download','analytics','participant_information','watermark','portfolio_website','team_login','private_client_galleries','find_my_photos'],'premium'=>['business_branding','client_favourites','download_controls','bulk_download','analytics','participant_information','watermark','portfolio_website','team_login','private_client_galleries','find_my_photos']];foreach($plans as$code=>$v){$id=DB::table('subscription_plans')->where('code',$code)->value('id');foreach(DB::table('subscription_features')->where('category','!=','limits')->get()as$f){$included=in_array($f->code,$matrix[$code],true);$addon=$code==='standard'&&$f->code==='watermark';DB::table('subscription_plan_features')->insertOrIgnore(['subscription_plan_id'=>$id,'subscription_feature_id'=>$f->id,'is_included'=>$included&&!$addon,'value_boolean'=>$included&&!$addon,'is_addon'=>$addon,'addon_price_paise'=>$addon?100000:null,'display_label'=>$f->name,'display_order'=>$f->display_order,'created_at'=>$now,'updated_at'=>$now]);}}}
}
